Boolean d2di_err_save (void)           
{ 
    d2di_vars.d2di_do_err_save = FALSE ;
    return (nvfs_wr(nvfs_d2di_protocol_error, &d2di_vars.err) == NVFS_OK);
}

//--------------------------------------------------------------------------//
void d2di_err_add (D2Di_Error_Code code)
{  
    UInt8 ptr = (d2di_vars.err.count % D2DI_ERR_BUFF_SIZE);
    d2di_vars.err.code[ptr] = code ;
    d2di_vars.err.count++ ;
    d2di_vars.d2di_do_err_save = TRUE ;
}
